py-ugadaj.py:
secret = 7
guess = int(input("Твоя догадка: "))
while guess != secret:
    if guess < secret:
        print("Больше!")
    else:
        print("Меньше!")
    guess = int(input("Твоя догадка: "))
print("Угадал! Это", secret)
